insert into passages (id, text, difficulty_level, b, active) values
('ceceb0f2-953e-40d1-87d2-4903d669d4a7', 'Maya is a nurse who works at a small clinic in a rural town. Every morning, she drives about thirty minutes to reach the clinic because there is no hospital closer to her home. Once she arrives, she checks on patients who stayed overnight and helps the doctor prepare for the day''s appointments. Maya says that the hardest part of her job is comforting worried family members, especially when a patient is very sick. On quieter days, she also teaches basic first aid classes to people in the community, which she says is one of her favorite parts of the job because it helps prevent future accidents.', 1, -2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('97e67cfb-421f-4bdc-bfa5-54a86035b12d', 'sentence_completion', 'My father ___ newspapers every morning before work.', NULL, '[{"id": "a", "text": "reads"}, {"id": "c", "text": "read"}, {"id": "d", "text": "readed"}, {"id": "b", "text": "reading"}]'::jsonb, 0, '{"strategy": "every morning = כל בוקר. הרגל קבוע בהווה, גוף שלישי יחיד.", "correct_reason": "reads = קורא. he/father + פועל בהווה מקבל s.", "options_analysis": ["נכון! father + פועל בהווה עם s, מתאים ל''every morning''", "חסר s לגוף שלישי יחיד", "readed אינה מילה — read הוא פועל לא רגולרי", "ing לבד ללא עזר לא תקין"]}', 0.64, -2.0, 0.25, 1, 'ai', NULL, true),
('0e23b34a-d1db-4d05-b08e-bc60a018c709', 'sentence_completion', 'The children ___ happy when they saw their new puppy.', NULL, '[{"id": "b", "text": "are"}, {"id": "a", "text": "were"}, {"id": "c", "text": "was"}, {"id": "d", "text": "is"}]'::jsonb, 1, '{"strategy": "when they saw = כאשר ראו. עבר, children = רבים.", "correct_reason": "were = היו. children רבים + עבר.", "options_analysis": ["are = הווה רבים — לא מתאים לעבר", "נכון! were = עבר רבים, מתאים ל-children ול-''saw'' שמרמז עבר", "was = עבר יחיד — לא מתאים ל-children שהוא רבים", "is = הווה יחיד — לא מתאים ל-children (רבים) ולעבר"]}', 0.55, -2.0, 0.25, 1, 'ai', NULL, true),
('427b24ad-3407-4143-904c-e82ee3d45ec5', 'sentence_completion', 'She is the ___ girl in her class.', NULL, '[{"id": "b", "text": "more tall"}, {"id": "a", "text": "taller"}, {"id": "d", "text": "tallest"}, {"id": "c", "text": "tall"}]'::jsonb, 2, '{"strategy": "in her class = בכיתה שלה. השוואה בין יותר משניים = עילית.", "correct_reason": "tallest = הגבוהה ביותר. ''the...in her class'' דורש עילית.", "options_analysis": ["more tall אינו תקין — משתמשים ב-taller או tallest", "taller = השוואתי — משמש בין שניים, לא ל''the...in her class''", "נכון! tallest = עילית, מתאים ל''the...in her class''", "tall = צורת יסוד — לא מתאימה ל''the...in her class''"]}', 0.64, -2.0, 0.25, 1, 'ai', NULL, true),
('d0ef8d39-e03b-4fcb-b212-b581adb696dc', 'sentence_completion', 'We ___ dinner when the phone rang.', NULL, '[{"id": "c", "text": "eat"}, {"id": "d", "text": "eating"}, {"id": "b", "text": "ate"}, {"id": "a", "text": "were eating"}]'::jsonb, 3, '{"strategy": "when the phone rang = כאשר הטלפון צלצל. פעולה מתמשכת שהופרעה בעבר = past continuous.", "correct_reason": "were eating = היינו אוכלים. פעולה מתמשכת בעבר שהופסקה על ידי פעולה אחרת.", "options_analysis": ["הווה — לא מתאים ל''rang'' שמרמז עבר", "ing לבד ללא עזר לא תקין", "עבר פשוט — פחות מתאים לתיאור פעולה מתמשכת שהופרעה", "נכון! were eating = past continuous, מתאים לפעולה שהופרעה"]}', 0.78, -2.0, 0.25, 1, 'ai', NULL, true),
('6f9fd93e-07a4-425b-9a2a-478a488739b6', 'sentence_completion', 'Don''t forget ___ the lights before you leave.', NULL, '[{"id": "b", "text": "to turn off"}, {"id": "d", "text": "turning off"}, {"id": "a", "text": "turned off"}, {"id": "c", "text": "turn off"}]'::jsonb, 0, '{"strategy": "Don''t forget + פועל = forget נדרש infinitive (to) כשמדובר במשימה שצריך לזכור לעשות.", "correct_reason": "to turn off = לכבות. forget + infinitive (to) לתיאור משימה עתידית שיש לזכור.", "options_analysis": ["נכון! forget + to + infinitive = משימה שיש לזכור לעשות", "turning off = gerund — forget + gerund מתייחס לזיכרון מהעבר, לא למשימה עתידית", "turned off = עבר — לא תקין אחרי forget", "turn off לבד ללא to לא תקין אחרי forget"]}', 0.68, -2.0, 0.25, 1, 'ai', NULL, true),
('f2cb5c87-f8a1-486b-b6f9-1aef2ce75065', 'sentence_completion', 'There isn''t ___ milk left in the fridge.', NULL, '[{"id": "c", "text": "a few"}, {"id": "a", "text": "much"}, {"id": "b", "text": "several"}, {"id": "d", "text": "many"}]'::jsonb, 1, '{"strategy": "milk הוא שם עצם לא ספיר. isn''t + לא ספיר דורש much.", "correct_reason": "much = הרבה. much משמש עם שם עצם לא ספיר בשלילה.", "options_analysis": ["a few משמש לספירים — milk לא נספר", "נכון! much מתאים לשם עצם לא ספיר כמו milk", "several משמש לספירים — milk לא נספר", "many משמש לספירים ברבים — milk לא נספר"]}', 0.86, -2.0, 0.25, 1, 'ai', NULL, true),
('1108c073-4fe0-4048-8b1d-21b78e1bc76f', 'sentence_completion', 'He is good ___ playing basketball.', NULL, '[{"id": "b", "text": "in"}, {"id": "a", "text": "for"}, {"id": "d", "text": "at"}, {"id": "c", "text": "on"}]'::jsonb, 2, '{"strategy": "good + preposition = צירוף קבוע. ''good at'' הוא הצירוף הנכון.", "correct_reason": "at = ב-. ''good at'' הוא הצירוף התקני לתיאור כישרון.", "options_analysis": ["in לא הצירוף הנכון עם good", "for לא הצירוף הנכון עם good", "נכון! good at = הצירוף התקני", "on לא הצירוף הנכון עם good"]}', 0.64, -2.0, 0.25, 1, 'ai', NULL, true),
('413ab0ed-2b3b-413b-bc63-c2fa2d9c7b60', 'sentence_completion', 'The train ___ from platform 3 in ten minutes.', NULL, '[{"id": "b", "text": "leaving"}, {"id": "d", "text": "leave"}, {"id": "a", "text": "left"}, {"id": "c", "text": "leaves"}]'::jsonb, 3, '{"strategy": "in ten minutes = בעוד עשר דקות — לוח זמנים קבוע, הווה פשוט משמש לתיאור לוחות זמנים עתידיים.", "correct_reason": "leaves = יוצאת. הווה פשוט לתיאור לוח זמנים קבוע (train), גם כשהזמן עתידי.", "options_analysis": ["leaving לבד ללא עזר לא תקין", "leave = חסר s — לא מתאים לגוף שלישי יחיד (train)", "left = עבר — לא מתאים ל''in ten minutes'' שמתאר עתיד", "נכון! leaves = הווה פשוט לתיאור לוח זמנים, מתאים גם לעתיד קרוב"]}', 0.57, -2.0, 0.25, 1, 'ai', NULL, true),
('2ef6022d-0077-433d-bfec-25b604984104', 'sentence_completion', 'I ___ to Paris twice in my life.', NULL, '[{"id": "c", "text": "have been"}, {"id": "d", "text": "was"}, {"id": "b", "text": "go"}, {"id": "a", "text": "went"}]'::jsonb, 0, '{"strategy": "twice in my life = פעמיים בחיי — ניסיון מצטבר עד עכשיו = present perfect.", "correct_reason": "have been = הייתי. present perfect מתאר ניסיון מצטבר עד הרגע הנוכחי.", "options_analysis": ["נכון! have been = present perfect, מתאים לניסיון מצטבר בחיים", "was = עבר יחיד פשוט — לא מתאים לתיאור ניסיון מצטבר", "go = הווה — לא מתאים לניסיון מצטבר מהעבר", "went = עבר פשוט — פחות מתאים ל''twice in my life'' שמתאר ניסיון כולל עד עכשיו"]}', 0.77, -2.0, 0.25, 1, 'ai', NULL, true),
('b891ca8f-b536-4eca-ba2e-a48b22620ed5', 'sentence_completion', 'The soup smells ___ ; what did you put in it?', NULL, '[{"id": "d", "text": "well"}, {"id": "b", "text": "good"}, {"id": "a", "text": "badly"}, {"id": "c", "text": "goodly"}]'::jsonb, 1, '{"strategy": "smells + adjective = פעלי חושים (smell, taste, feel) מקבלים תואר, לא תואר הפועל.", "correct_reason": "good = טוב. אחרי smell (verb of senses) בא adjective, לא adverb.", "options_analysis": ["well הוא adverb — לא מתאים אחרי smell שדורש adjective", "נכון! smell + adjective (good) = תבנית תקנית לפעלי חושים", "badly הוא adverb — לא מתאים אחרי smell שדורש adjective", "goodly אינה מילה תקנית באנגלית מודרנית"]}', 0.9, -2.0, 0.25, 1, 'ai', NULL, true),
('f8a7335b-2fc6-4062-9fab-a7af6356da3e', 'sentence_completion', 'She asked me ___ I wanted to join them for dinner.', NULL, '[{"id": "a", "text": "that"}, {"id": "b", "text": "which"}, {"id": "c", "text": "if"}, {"id": "d", "text": "what"}]'::jsonb, 2, '{"strategy": "asked...I wanted = שאלה...רציתי. שאלה עקיפה של כן/לא (yes/no question) משתמשת ב-if.", "correct_reason": "if = האם. שאלה עקיפה מסוג כן/לא (yes/no) מתחילה ב-if או whether.", "options_analysis": ["that לא מתאים לשאלה עקיפה מסוג כן/לא", "which מתאים לבחירה בין אפשרויות, לא לשאלת כן/לא", "נכון! if מתאים לשאלה עקיפה מסוג כן/לא", "what מתאים לשאלת מידע ספציפית, לא לשאלת כן/לא"]}', 0.62, -2.0, 0.25, 1, 'ai', NULL, true),
('536aef8c-a053-4c15-83c5-c81ee1958e86', 'sentence_completion', 'The children are playing ___ the garden.', NULL, '[{"id": "d", "text": "at"}, {"id": "b", "text": "on"}, {"id": "a", "text": "to"}, {"id": "c", "text": "in"}]'::jsonb, 3, '{"strategy": "playing...garden = משחקים...בגן. תיאור מיקום בתוך שטח סגור/מוגדר.", "correct_reason": "in = ב-. ''in the garden'' מתאר מיקום בתוך שטח מוגדר.", "options_analysis": ["at משמש לנקודה ספציפית, לא לשטח כמו גן", "on משמש למשטח, לא לשטח פתוח כמו גן", "to משמש לכיוון, לא למיקום נוכחי", "נכון! in the garden = הצירוף התקני למיקום בתוך שטח מוגדר"]}', 0.84, -2.0, 0.25, 1, 'ai', NULL, true),
('7e03f4dc-25aa-4cab-bffa-959a848bb7b2', 'restatement', 'The store sells clothes, shoes, and accessories.', NULL, '[{"id": "a", "text": "The store offers clothes, shoes, and accessories for sale."}, {"id": "b", "text": "The store does not sell anything."}, {"id": "d", "text": "The store only sells clothes."}, {"id": "c", "text": "The store sells only shoes."}]'::jsonb, 0, '{"strategy": "sells clothes, shoes, and accessories = מוכרת בגדים, נעליים ואביזרים. רשימת פריטים.", "correct_reason": "אותה משמעות בדיוק: מציעה בגדים, נעליים ואביזרים למכירה.", "options_analysis": ["נכון! אותה משמעות בדיוק: מציעה בגדים, נעליים ואביזרים", "הפוך — סותר את קיום החנות שמוכרת", "סותר את הרשימה המלאה — יש עוד פריטים", "סותר את הרשימה המלאה — יש עוד פריטים"]}', 0.55, -2.0, 0.25, 1, 'ai', NULL, true),
('eae282ba-8105-4651-a7e2-34faaa893644', 'restatement', 'He plays the guitar every weekend.', NULL, '[{"id": "b", "text": "He does not own a guitar."}, {"id": "a", "text": "He plays the guitar on Saturdays and Sundays."}, {"id": "d", "text": "He never plays the guitar."}, {"id": "c", "text": "He plays the guitar only on weekdays."}]'::jsonb, 1, '{"strategy": "every weekend = כל סוף שבוע = שבת וראשון.", "correct_reason": "אותה משמעות בדיוק: מנגן בגיטרה בשבתות ובימי ראשון.", "options_analysis": ["סותר את קיום הגיטרה שמנגן עליה", "נכון! אותה משמעות בדיוק: מנגן בסופי שבוע = שבת וראשון", "הפוך — סותר ''plays the guitar every weekend''", "הפוך — ''weekdays'' סותר ''weekend''"]}', 0.62, -2.0, 0.25, 1, 'ai', NULL, true),
('37545d6d-aba1-41b8-a40c-6cbafe85ab1e', 'restatement', 'The children are afraid of the dark.', NULL, '[{"id": "d", "text": "The children love the dark."}, {"id": "a", "text": "There is no darkness where the children live."}, {"id": "c", "text": "The children feel scared when it is dark."}, {"id": "b", "text": "The children are never scared of anything."}]'::jsonb, 2, '{"strategy": "afraid of the dark = פוחדים מהחושך.", "correct_reason": "אותה משמעות בדיוק: חשים פחד כשחשוך.", "options_analysis": ["הפוך — ''love'' סותר ''afraid''", "לא נאמר במקור ולא רלוונטי לפחד המתואר", "נכון! אותה משמעות בדיוק: חשים פחד כשחשוך", "הפוך — סותר ''afraid of the dark''"]}', 0.7, -2.0, 0.25, 1, 'ai', NULL, true),
('7ebdb899-962d-4b18-a022-b6ed5e5823e2', 'restatement', 'This box is too heavy for me to lift.', NULL, '[{"id": "d", "text": "This box is very light."}, {"id": "a", "text": "I have already lifted this box many times."}, {"id": "b", "text": "I can easily lift this box by myself."}, {"id": "c", "text": "This box is so heavy that I cannot lift it alone."}]'::jsonb, 3, '{"strategy": "too heavy for me to lift = כבד מדי בשבילי להרים. תוצאה.", "correct_reason": "אותה משמעות בדיוק: כבד מדי, לא מסוגל להרים לבד.", "options_analysis": ["הפוך — ''light'' סותר ''heavy''", "סותר ''too heavy...to lift'' — עדיין לא הצליח להרים", "הפוך — סותר ''too heavy for me to lift''", "נכון! אותה משמעות בדיוק: כבד מדי, לא יכול להרים לבד"]}', 0.51, -2.0, 0.25, 1, 'ai', NULL, true),
('29df710a-a8fc-4e16-b4bf-36d5bad25366', 'restatement', 'The bakery is famous for its fresh bread.', NULL, '[{"id": "b", "text": "The bakery is known for making fresh bread."}, {"id": "a", "text": "No one knows about the bakery."}, {"id": "c", "text": "The bakery never sells bread."}, {"id": "d", "text": "The bakery only sells old bread."}]'::jsonb, 0, '{"strategy": "famous for its fresh bread = מפורסמת בזכות הלחם הטרי שלה.", "correct_reason": "אותה משמעות בדיוק: ידועה בהכנת לחם טרי.", "options_analysis": ["נכון! אותה משמעות בדיוק: ידועה בהכנת לחם טרי", "הפוך — ''famous'' סותר ''no one knows''", "הפוך — סותר ''famous for its fresh bread''", "הפוך — ''fresh'' סותר ''old bread''"]}', 0.6, -2.0, 0.25, 1, 'ai', NULL, true),
('643fe353-2c5c-452a-acc1-9ef93a3eeb21', 'restatement', 'My uncle lives in a small village near the mountains.', NULL, '[{"id": "c", "text": "My uncle lives in a large city."}, {"id": "a", "text": "My uncle''s home is a small village close to the mountains."}, {"id": "d", "text": "My uncle lives far from any mountains."}, {"id": "b", "text": "My uncle does not have a home."}]'::jsonb, 1, '{"strategy": "lives in a small village near the mountains = גר בכפר קטן ליד ההרים.", "correct_reason": "אותה משמעות בדיוק: ביתו כפר קטן קרוב להרים.", "options_analysis": ["הפוך — ''large city'' סותר ''small village''", "נכון! אותה משמעות בדיוק: ביתו כפר קטן קרוב להרים", "הפוך — ''far from'' סותר ''near the mountains''", "סותר את קיום הבית שתואר"]}', 0.84, -2.0, 0.25, 1, 'ai', NULL, true),
('d169bb23-8be5-4ff0-850b-cb209d37ca8a', 'restatement', 'The concert tickets sold out within an hour.', NULL, '[{"id": "c", "text": "The tickets took a whole week to sell."}, {"id": "d", "text": "No one wanted to buy the tickets."}, {"id": "a", "text": "All the concert tickets were sold in less than an hour."}, {"id": "b", "text": "The concert tickets never sold."}]'::jsonb, 2, '{"strategy": "sold out within an hour = אזלו תוך שעה.", "correct_reason": "אותה משמעות בדיוק: כל הכרטיסים נמכרו בפחות משעה.", "options_analysis": ["הפוך — סותר ''within an hour''", "הפוך — סותר ''sold out'' שמרמז ביקוש גבוה", "נכון! אותה משמעות בדיוק: כל הכרטיסים נמכרו בפחות משעה", "הפוך — סותר ''sold out within an hour''"]}', 0.84, -2.0, 0.25, 1, 'ai', NULL, true),
('4c12e263-5d2e-43a4-9c4a-5011d85f0457', 'restatement', 'The children built a sandcastle on the beach.', NULL, '[{"id": "c", "text": "The children destroyed a sandcastle on the beach."}, {"id": "d", "text": "The children built a house made of bricks."}, {"id": "b", "text": "The children never went to the beach."}, {"id": "a", "text": "On the beach, the children constructed a castle made of sand."}]'::jsonb, 3, '{"strategy": "built a sandcastle on the beach = בנו טירת חול על החוף.", "correct_reason": "אותה משמעות בדיוק: בנו על החוף טירה עשויה חול.", "options_analysis": ["הפוך — ''destroyed'' סותר ''built''", "הפוך — ''sandcastle'' סותר ''house made of bricks''", "הפוך — סותר ''on the beach''", "נכון! אותה משמעות בדיוק: בנו טירה עשויה חול על החוף"]}', 0.76, -2.0, 0.25, 1, 'ai', NULL, true),
('fad95a8d-4aee-405b-b463-e0a6231f1236', 'restatement', 'The old man walks slowly with a cane.', NULL, '[{"id": "a", "text": "The old man moves slowly and uses a cane for support."}, {"id": "b", "text": "The old man never leaves his house."}, {"id": "d", "text": "The old man walks without any help."}, {"id": "c", "text": "The old man runs very fast."}]'::jsonb, 0, '{"strategy": "walks slowly with a cane = הולך לאט עם מקל.", "correct_reason": "אותה משמעות בדיוק: נע לאט ונעזר במקל.", "options_analysis": ["נכון! אותה משמעות בדיוק: נע לאט ונעזר במקל", "סותר את קיום ההליכה שתוארה", "הפוך — סותר ''with a cane''", "הפוך — ''runs very fast'' סותר ''walks slowly''"]}', 0.54, -2.0, 0.25, 1, 'ai', NULL, true),
('3db666b2-fc82-4d5a-a4b8-d0a9571fa067', 'restatement', 'The museum is open from 9 AM to 5 PM every day.', NULL, '[{"id": "d", "text": "The museum is always closed."}, {"id": "a", "text": "The museum''s hours are 9 in the morning until 5 in the evening, daily."}, {"id": "b", "text": "The museum is only open on weekends."}, {"id": "c", "text": "The museum has no fixed schedule."}]'::jsonb, 1, '{"strategy": "open from 9 AM to 5 PM every day = פתוח מ-9 בבוקר עד 5 אחה''צ כל יום.", "correct_reason": "אותה משמעות בדיוק: שעות פתיחה 9 בבוקר עד 5 בערב, מדי יום.", "options_analysis": ["הפוך — סותר ''open from 9 AM to 5 PM''", "נכון! אותה משמעות בדיוק: שעות פתיחה זהות, מדי יום", "הפוך — סותר ''every day''", "הפוך — סותר לוח הזמנים הקבוע שתואר"]}', 0.74, -2.0, 0.25, 1, 'ai', NULL, true),
('3cf74f32-83d8-46fd-84a1-8a6db291528c', 'restatement', 'She always brings an umbrella when it might rain.', NULL, '[{"id": "a", "text": "She forgets her umbrella most of the time."}, {"id": "b", "text": "She never carries an umbrella."}, {"id": "d", "text": "When there''s a chance of rain, she always takes an umbrella with her."}, {"id": "c", "text": "She only brings an umbrella when it''s sunny."}]'::jsonb, 2, '{"strategy": "always brings...when it might rain = תמיד מביאה...כשעלול לרדת גשם.", "correct_reason": "אותה משמעות בדיוק: כשיש סיכוי לגשם, תמיד לוקחת מטרייה.", "options_analysis": ["הפוך — ''always'' סותר ''forgets...most of the time''", "הפוך — סותר ''always brings an umbrella''", "נכון! אותה משמעות בדיוק: כשיש סיכוי לגשם, תמיד לוקחת מטרייה", "הפוך — ''sunny'' סותר ''might rain''"]}', 0.67, -2.0, 0.25, 1, 'ai', NULL, true),
('5c3c32de-d07f-4b01-8324-f8fdc02442b3', 'restatement', 'The kitchen was full of the smell of fresh cookies.', NULL, '[{"id": "a", "text": "No cookies were ever baked in that kitchen."}, {"id": "d", "text": "The kitchen smelled like fresh bread instead."}, {"id": "c", "text": "The kitchen had no smell at all."}, {"id": "b", "text": "The smell of freshly baked cookies filled the kitchen."}]'::jsonb, 3, '{"strategy": "full of the smell of fresh cookies = מלאה בריח עוגיות טריות.", "correct_reason": "אותה משמעות בדיוק: ריח עוגיות טריות מילא את המטבח.", "options_analysis": ["סותר את קיום העוגיות שנאפו", "סותר ''cookies'' — הריח היה של עוגיות, לא לחם", "הפוך — סותר ''full of the smell''", "נכון! אותה משמעות בדיוק: ריח עוגיות טריות מילא את המטבח"]}', 0.62, -2.0, 0.25, 1, 'ai', NULL, true),
('8049ca42-7f18-4ac4-8776-6921bd419d13', 'reading_comprehension', 'What is Maya''s job?', 'ceceb0f2-953e-40d1-87d2-4903d669d4a7', '[{"id": "d", "text": "She is a nurse"}, {"id": "b", "text": "She is a driver"}, {"id": "a", "text": "She is a teacher"}, {"id": "c", "text": "She is a doctor"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את תפקידה של מאיה בפסקה.", "correct_reason": "הפסקה אומרת: ''Maya is a nurse''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה — היא נוסעת לעבודה, זה לא תפקידה", "זה רק חלק מתפקידה, לא התפקיד המרכזי", "לא נאמר בפסקה — היא עוזרת לרופא, לא הרופאה עצמה"]}', 0.51, -2.0, 0.25, 1, 'ai', NULL, true),
('c1c266bb-677f-4b72-8f21-e2fe7a65e6e4', 'reading_comprehension', 'How long does it take Maya to drive to the clinic?', 'ceceb0f2-953e-40d1-87d2-4903d669d4a7', '[{"id": "c", "text": "She does not drive to work"}, {"id": "a", "text": "About thirty minutes"}, {"id": "b", "text": "About one hour"}, {"id": "d", "text": "About ten minutes"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את זמן הנסיעה בפסקה.", "correct_reason": "הפסקה אומרת: ''she drives about thirty minutes to reach the clinic''.", "options_analysis": ["סותר את הפסקה שמתארת נסיעה יומית", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 0.55, -2.0, 0.25, 1, 'ai', NULL, true),
('ac288e39-d80d-4179-931b-3dff3eb174d0', 'reading_comprehension', 'According to the passage, what does Maya say is the hardest part of her job?', 'ceceb0f2-953e-40d1-87d2-4903d669d4a7', '[{"id": "b", "text": "Driving to work every day"}, {"id": "a", "text": "Waking up early"}, {"id": "c", "text": "Comforting worried family members"}, {"id": "d", "text": "Teaching first aid classes"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את מה שמאיה אומרת שהכי קשה.", "correct_reason": "הפסקה אומרת: ''the hardest part of her job is comforting worried family members''.", "options_analysis": ["לא מוזכר כחלק הקשה ביותר בפסקה", "לא מוזכר בפסקה כלל", "נכון! נאמר במפורש בפסקה", "הפוך — זה חלק שהיא אוהבת, לא הכי קשה"]}', 0.83, -2.0, 0.25, 1, 'ai', NULL, true),
('0cc3ea15-d32e-49dd-8f18-1917c427b2fc', 'reading_comprehension', 'What does Maya teach on quieter days, according to the passage?', 'ceceb0f2-953e-40d1-87d2-4903d669d4a7', '[{"id": "c", "text": "Nursing school courses"}, {"id": "a", "text": "Cooking classes"}, {"id": "d", "text": "Driving lessons"}, {"id": "b", "text": "Basic first aid classes"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש מה מאיה מלמדת בפסקה.", "correct_reason": "הפסקה אומרת: ''she also teaches basic first aid classes to people in the community''.", "options_analysis": ["לא נאמר בפסקה כלל", "לא נאמר בפסקה כלל", "לא נאמר בפסקה כלל", "נכון! נאמר במפורש בפסקה"]}', 0.84, -2.0, 0.25, 1, 'ai', NULL, true);